/**
 * Interprets up to {@code maxBytes} bytes from the input as an unsigned big-endian
 * integer. If the input has fewer than maxBytes bytes, the data occupies the
 * most-significant byte positions (preserving sort order for variable-length strings).
 * If the input has more bytes than maxBytes, only the first maxBytes are used.
 *
 * <p>Examples with maxBytes=2: {0x41, 0x42} → 0x4142, {0x41} → 0x4100
 */
private static long bytesToUnsignedLong(byte[] data, int maxBytes) {
    assert data != null : "data must not be null";
    final int useBytes = Math.min(data.length, maxBytes);
    long result = 0;
    for (int i = 0; i < useBytes; i++) {
        result |= (data[i] & 0xFFL) << (8 * (maxBytes - 1 - i));
    }
    return result;
}
